import hashlib
import hmac
import os
import time
import re
from functools import wraps
from flask import Flask, request, jsonify, g
import sqlite3
import struct

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['DATABASE'] = '/tmp/rbac_app.db'

# Permission bit flags (32-bit system)
PERM_READ = 0x00000001
PERM_WRITE = 0x00000002
PERM_DELETE = 0x00000004
PERM_ADMIN = 0x80000000  # Highest bit = admin
PERM_AUDIT = 0x00000008
PERM_EXPORT = 0x00000010

ROLE_PERMISSIONS = {
    'viewer': PERM_READ,
    'editor': PERM_READ | PERM_WRITE,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_AUDIT,
    'admin': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_AUDIT | PERM_EXPORT | PERM_ADMIN,
}

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        permissions INTEGER NOT NULL DEFAULT 1,
        session_token TEXT,
        token_expires REAL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        timestamp REAL,
        details TEXT
    )''')
    db.commit()
    db.close()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(stored_hash, password):
    parts = stored_hash.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), parts[1])

def generate_session_token():
    return os.urandom(32).hex()

def compute_effective_permissions(base_permissions, delegated_permissions=None):
    """Compute effective permissions by combining base and delegated.
    Uses 32-bit signed arithmetic to match legacy C backend."""
    effective = base_permissions
    if delegated_permissions is not None:
        # Combine permissions using bitwise OR
        combined = effective | delegated_permissions
        # Truncate to 32-bit signed integer (legacy compatibility)
        combined = struct.unpack('>i', struct.pack('>I', combined & 0xFFFFFFFF))[0]
        effective = combined
    return effective

def has_permission(user_permissions, required_permission):
    """Check if user has the required permission bit set.
    Handles 32-bit signed representation from legacy system."""
    # Convert to unsigned 32-bit for comparison
    user_perm_unsigned = user_permissions & 0xFFFFFFFF
    req_perm_unsigned = required_permission & 0xFFFFFFFF
    return (user_perm_unsigned & req_perm_unsigned) == req_perm_unsigned

def is_admin(user_permissions):
    """Check if user has admin privileges.
    Admin bit is 0x80000000 (sign bit in signed 32-bit)."""
    # Check if the permission value indicates admin access
    # In signed 32-bit, admin bit set means negative value
    effective = compute_effective_permissions(user_permissions)
    return effective < 0  # Admin bit (0x80000000) makes it negative in signed repr

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401

        db = get_db()
        user = db.execute(
            'SELECT * FROM users WHERE session_token = ? AND token_expires > ?',
            (token, time.time())
        ).fetchone()

        if not user:
            return jsonify({'error': 'Invalid or expired session'}), 401

        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_permission(permission):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if not hasattr(g, 'current_user'):
                return jsonify({'error': 'Authentication required'}), 401

            user_perms = g.current_user['permissions']
            if not has_permission(user_perms, permission):
                return jsonify({'error': 'Insufficient permissions'}), 403

            return f(*args, **kwargs)
        return decorated
    return decorator

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not hasattr(g, 'current_user'):
            return jsonify({'error': 'Authentication required'}), 401

        user_perms = g.current_user['permissions']
        if not is_admin(user_perms):
            return jsonify({'error': 'Admin access required'}), 403

        return f(*args, **kwargs)
    return decorated

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return jsonify({'error': 'Invalid username format'}), 400

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()

    if not user or not verify_password(user['password_hash'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_session_token()
    expires = time.time() + 3600

    db.execute(
        'UPDATE users SET session_token = ?, token_expires = ? WHERE id = ?',
        (token, expires, user['id'])
    )
    db.commit()

    return jsonify({
        'token': token,
        'expires': expires,
        'permissions': user['permissions']
    })

@app.route('/api/auth/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    password = data['password']

    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return jsonify({'error': 'Invalid username format'}), 400

    if len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400

    password_hash = hash_password(password)

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, permissions) VALUES (?, ?, ?)',
            (username, password_hash, PERM_READ)
        )
        db.commit()
        return jsonify({'message': 'User created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/users/delegate', methods=['POST'])
@require_auth
@require_permission(PERM_WRITE)
def delegate_permissions():
    """Allow a user to delegate subset of their permissions to another user."""
    data = request.get_json()
    if not data or 'target_user' not in data or 'permissions' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    target_username = data['target_user']
    delegated_perms = int(data['permissions'])

    current_user_perms = g.current_user['permissions']

    # Ensure user can only delegate permissions they themselves have
    # Mask the delegated permissions with current user's permissions
    safe_delegated = delegated_perms & current_user_perms

    db = get_db()
    target = db.execute('SELECT * FROM users WHERE username = ?', (target_username,)).fetchone()
    if not target:
        return jsonify({'error': 'Target user not found'}), 404

    # Compute new permissions for target
    new_perms = compute_effective_permissions(target['permissions'], safe_delegated)

    db.execute(
        'UPDATE users SET permissions = ? WHERE id = ?',
        (new_perms, target['id'])
    )
    db.commit()

    # Audit log
    db.execute(
        'INSERT INTO audit_log (user_id, action, timestamp, details) VALUES (?, ?, ?, ?)',
        (g.current_user['id'], 'delegate', time.time(),
         f'Delegated {safe_delegated} to {target_username}')
    )
    db.commit()

    return jsonify({'message': 'Permissions delegated', 'new_permissions': new_perms})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_all_users():
    db = get_db()
    users = db.execute('SELECT id, username, permissions FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

@app.route('/api/admin/set-role', methods=['POST'])
@require_auth
@require_admin
def set_user_role():
    data = request.get_json()
    if not data or 'username' not in data or 'role' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    role = data['role']
    if role not in ROLE_PERMISSIONS:
        return jsonify({'error': 'Invalid role'}), 400

    db = get_db()
    db.execute(
        'UPDATE users SET permissions = ? WHERE username = ?',
        (ROLE_PERMISSIONS[role], data['username'])
    )
    db.commit()
    return jsonify({'message': f'Role set to {role}'})

@app.route('/api/data/export', methods=['GET'])
@require_auth
@require_permission(PERM_EXPORT)
def export_data():
    db = get_db()
    logs = db.execute('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 100').fetchall()
    return jsonify({'audit_logs': [dict(l) for l in logs]})

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
